from decimal import Decimal
from typing import Any


def _numeric_line_no(value: Any) -> Decimal:
    """Convert a legacy LINE_NO value for numeric ordering."""
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted lines and renumber surviving lines per order."""
    grouped: dict[str, list[tuple[Decimal, int, dict]]] = {}

    for position, row in enumerate(lines):
        if row.get("DEL_FLG", "") == "Y":
            continue

        order_id = str(row.get("ORD_ID", ""))
        line_no = _numeric_line_no(row.get("LINE_NO", ""))
        grouped.setdefault(order_id, []).append((line_no, position, row))

    result: list[dict] = []

    for order_id in sorted(grouped):
        ordered_rows = sorted(
            grouped[order_id],
            key=lambda item: (item[0], item[1]),
        )

        for new_line_no, (_, _, row) in enumerate(ordered_rows, start=1):
            migrated_row = dict(row)
            migrated_row["LINE_NO"] = new_line_no
            result.append(migrated_row)

    return result
